/**
 * next/image loader for the static export, which has no image server.
 * Each `srcset` width resolves to a pre-resized copy in public/image-variants
 * (listed in src/lib/image-variants.ts, generated by `npm run images`).
 * public/ is copied by `next build` itself, so every host deploys the copies.
 */
import { imageVariants } from "./image-variants";

type LoaderArgs = { src: string; width: number; quality?: number };

export default function imageLoader({ src, width }: LoaderArgs) {
  const entry = imageVariants.get(src);
  if (!entry) return src;
  const variant = entry.variants.find(([w]) => w >= width);
  if (variant) return variant[1];
  // At or above the original's width the original is served. The fixed query
  // keeps that a single URL and shows Next's dev check that width is handled.
  const join = src.includes("?") ? "&" : "?";
  return `${src}${join}w=${entry.original.width}`;
}
